with base as (select id, customer_id, store_id, status, channel, shipping_fee, amount - shipping_fee as amount_with_shipping, coalesce(channel, 'UNKNOWN') as resolved_channel from orders where store_id is not null) select s.id, s.status, s.amount_with_shipping, x.quantity, x.order_item_unit_price from base s left join lateral (select c.quantity, c.unit_price as order_item_unit_price from order_items c where c.order_id = s.id order by c.unit_price desc, c.id desc limit 1) x on true;
